export function translator(language:Language){return (key:string)=>rows[key]?.[languages.indexOf(language)]||key;}
export function label(key:string,t:(key:string)=>string){const trimmed=key.replace(/_([a-z])/g,(_,s)=>s.toUpperCase());const translated=t(trimmed);return translated===trimmed?key.replace(/([a-z])([A-Z])/g,'$1 $2').replaceAll('_',' '):translated;}
export function statusLabel(value:string,t:(key:string)=>string){const map:Record<string,string>={DRAFT:'draft',OPEN:'pending',PENDING:'pending',ACTIVE:'active',WORKING:'working',ACCEPT:'accept',REJECT:'rejected',APPROVE:'approve',DISPUTE:'dispute',AWAY_PENDING_REASON:'attention',SERVICE_TASK:'service',WAITING_WORK:'waiting',IN_PROGRESS:'working',ON_BREAK:'break',PRIVATE_BREAK:'break',APPROVED:'approved',ACCEPTED:'approved',COMPLETED:'completed',CLOSED:'completed',ENDED:'completed',DONE:'completed',SUBMITTED:'review',QUALITY_REVIEW:'review',REJECTED:'rejected',RETURNED:'rejected',READY:'plan',PLANNED:'plan',PAID:'completed'};return t(map[value]||value);}
